/** Return questions filtered by competency and/or year group. */
export function getQuestions(
  competency?: CompetencyCode,
  yearGroup?: YearGroup,
): LomloeQuestion[] {
  return LOMLOE_QUESTIONS.filter(q => {
    if (competency && q.competency !== competency) return false;
    if (yearGroup && q.yearGroup !== yearGroup) return false;
    return true;
  });
}

/** Return coverage stats: questions per competency per year group. */
export function getCoverageStats() {
  const stats: Record<string, Record<string, number>> = {};
  for (const q of LOMLOE_QUESTIONS) {
    if (!stats[q.competency]) stats[q.competency] = {};
    stats[q.competency][q.yearGroup] = (stats[q.competency][q.yearGroup] ?? 0) + 1;
  }
  return stats;
}
